import React, { useEffect, useState, memo } from 'react';
import { Form, Modal, Input, message, Spin } from 'antd';
import axios from 'axios';
import isEmail from 'validator/lib/isEmail';
import ReCAPTCHA from 'react-google-recaptcha'


const forgotPasswordUrl = `${process.env.AUTH_API_URL}/user/forgot-password`;
const ForgotPasswordForm = () => {
  const recaptchaRef = React.useRef()
  const [modalVisible, setModalVisible] = useState(false);
  const [forgotLoading, setForgotLoading] = useState(false);
  const [form] = Form.useForm();
  const handleCancel = () => {
    form.resetFields();
    setModalVisible(false);
  };
  const handleResetPassword = async (values) => {
    setForgotLoading(true);
    const captchaToken = await recaptchaRef.current.executeAsync()

    if (isEmail(values.email.trim()))
      axios
        .post(
          forgotPasswordUrl,
          {
            email: values.email.trim().toLowerCase(),
            captchaToken,
          },
          { withCredentials: true }
        )
        .then((response) => {
          setForgotLoading(false);
          setModalVisible(false);
          Modal.success({
            title: '',
            content: response.data.message,
            okText: 'Ok',
          });
        })
        .catch((error) => {
          setForgotLoading(false);
          const errorMessage = error.response?.data?.error?.email?.[0] || error.response?.data?.error?.message || 'Something went wrong. Please try again later.';
          message.error(errorMessage, 2);
        });
    else {
      setForgotLoading(false);
      message.error('Please enter a valid address!');
    }
  };
  const onBtnCreate = async () => {
    const values = await form.validateFields();
    handleResetPassword(values);
  };
  const showModal = () => {
    setModalVisible(true);
  };

  useEffect(() => {
    if (modalVisible) form.resetFields();
  }, [modalVisible]);
  return (
    <>
      <div className="forgot-link">
        <a onClick={showModal} href="#!" id="ForgotPwdLink">
          Forgot password?
        </a>
      </div>
      <Modal
        visible={modalVisible}
        title="Reset Password"
        okText="Reset"
        onCancel={() => handleCancel()}
        onOk={() => onBtnCreate()}
        confirmLoading={forgotLoading}
        cancelText="Cancel"
        wrapClassName="onboard-modal"
      >
        <Form
          form={form}
          layout="vertical"
          className="reset-pass"
          autoComplete="off"
          name="forgot-password-form"
        >
          <p>
            To reset your password, enter the email address you registered with
          </p>
          <Form.Item
            name="email"
            rules={[
              {
                required: true,
                message: 'Enter the email address you registered with.',
              },
            ]}
          >
            <Input
              onPressEnter={(e) =>
                handleResetPassword({ email: e.target.value })
              }
              placeholder="Enter email"
              style={{ height: '40px' }}
              autoFocus
            />
          </Form.Item>
          <ReCAPTCHA
              ref={recaptchaRef}
              size='invisible'
              sitekey={process.env.SITE_KEY}
                />
        </Form>
      </Modal>
    </>
  );
};
export default memo(ForgotPasswordForm);
