import React, { useEffect } from 'react'
import { Form, Modal, Input } from 'antd'

const TwoFACodeForm = (props) => {
  const { mfaModal, isLoading, handleSubmit, handleMfaModal } = props
  const [form] = Form.useForm()
  const onFormSubmit = async () => {
    const values = await form.validateFields()
    handleSubmit({ otp: values.otp })
  }
  useEffect(() => {
    if(mfaModal) form.resetFields()
  }, [mfaModal])
  return (
    <Modal
      title='Multi-factor authentication'
      visible={mfaModal}
      onOk={() => onFormSubmit()}
      confirmLoading={isLoading}
      okText='Authenticate'
      onCancel={() => {
        form.resetFields()
        handleMfaModal(false)
      }}
    >
      <Form
        form={form}
        layout='vertical'
        className='reset-pass'
        autoComplete='off'
        name='two-fa-form'
      >
        <Form.Item
          name='otp'
          rules={[
            {
              required: true,
              message: 'Please enter your authentication code.',
            },
          ]}
        >
          <Input
            onPressEnter={onFormSubmit}
            autoFocus
            placeholder='Enter authentication code'
          />
        </Form.Item>
      </Form>
    </Modal>
  )
}
export default TwoFACodeForm
