import React, { useState } from 'react';
import { Button, message } from 'antd';
import Alert from 'react-s-alert';
import axios from 'axios';
import { axiosInstance } from 'services/globalInstance';
import { tokenRefreshManager } from 'services/tokenRefreshManager';
import isEmail from 'validator/lib/isEmail';
import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import styled from 'styled-components';
import authApi from 'services/authApi';
import { isProd } from 'Utils/constants/variables';
import { rollbar } from 'components/common/rollbar';
import TwoFACodeForm from './TwoFACodeForm';

let cancel = null;
let request = 0;
const { CancelToken } = axios;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: flex-start;

  button {
    font-size: 1.125rem;
    line-height: 1.75rem;
    font-family: 'Poppins', Verdana, sans-serif;
    font-weight: 500;
    color: #ffffff;
    padding: 10px 24px;
    height: initial;
    border-radius: 4px;
    text-transform: initial;
    background-color: #5d97ff;
    transition: all 0.1s ease-in-out;

    &:hover {
      background-color: #151e35;
    }
  }

  @media screen and (min-width: 700px) {
    justify-content: center;
  }
`;

const LoginSubmitButton = (props) => {
  const {
    getFieldValue,
    getFieldsError,
    token,
    redirectUrl,
    isValidRedirectUrl,
    customer,
    mixpanel,
    form,
    shouldBeEnabled,
    secret
  } = props;
  const [isLoading, setIsLoading] = useState(false);
  const [mfaModal, setMfaModal] = useState(false);
  const mixpanelEventCapture = (responseData) => {
    mixpanel.identify(responseData.memberId);
    mixpanel.track('Logged In', {
      login_method: responseData.loginMethod,
      organization_id: responseData.organization
        ? `${responseData.organization.name}_${responseData.organization.id}`
        : '',
      memberId: responseData.memberId,
    });
    mixpanel.people.increment('# of Login', 1);
  };

  const handleSubmit = async ({ otp } = {}) => {
    setIsLoading(true);

    // @Note: This is to ensure the form is validated before submitting when autofilling with 1password
    // eslint-disable-next-line no-promise-executor-return
    await new Promise(resolve => setTimeout(resolve, 0));
  
    request++;
    if (cancel) await cancel(request);
    try {
      const values = await form.validateFields();
      const email = values.email.trim();
      if (isEmail(email)) {
        Alert.closeAll();
        const d = new Date();
        const postData = {
          email,
          password: values.password,
          otp,
          timezone: d.toString().split('GMT')[1].split(' (')[0],
          token,
        };
        if (redirectUrl?.includes('secret')) {
          postData.token = undefined;
          postData.secret = secret;
        }

        await fetch(`${process.env.API_URL}/auth/login`, {
          credentials: 'include',
        });
        await axiosInstance({
          method: 'post',
          url: `${process.env.AUTH_API_URL}/login`,
          data: postData,
          withCredentials: true,
          cancelToken: new CancelToken((c) => {
            cancel = c;
            request = 0;
          }),
          validateStatus(status) {
            return status >= 200 && status <= 302;
          },
        })
          .then(async (response) => {
            try {
              localStorage.setItem('tokenResponse', JSON.stringify(response));
              localStorage.setItem('tokenCallGetTime', new Date().getTime());
              localStorage.setItem('loginState', true);
            } catch (err) {
              // silent fail
            }

            cancel = null;
            tokenRefreshManager.start(response.data?.data?.expires_at);
            if (customer && !redirectUrl?.includes('secret'))
              await authApi.teamInvitationAccept(token);
            if (response.data && isProd)
              mixpanelEventCapture(response.data.data);
            if (redirectUrl && isValidRedirectUrl)
              redirectUrlHandler(redirectUrl);
            else window.location.href = `${process.env.REDIRECT_URL}/dashboard`;
          })
          .catch((error) => {
            let alertErr;
            cancel = null;
            Alert.closeAll();
            setIsLoading(false);
            if (error.response) {
              if (error.response.data.error.message) {
                alertErr = !error.response.data.error.message.includes(
                  'authentication'
                )
                  ? error.response.data.error.message
                  : '';
              } else if (error.response.data.error.email) {
                alertErr = error.response.data.error.email[0];
              } else if (error.response.data.error.otp) {
                if (!error.response.data.mfa_required) {
                  message.destroy();
                  message.error(error.response.data.error.otp[0]);
                }
              } else alertErr = error.response.data.error.password[0];
              if (error.response.data.mfa_required) setMfaModal(true);
            } else {
              alertErr = 'Something went wrong!'
              rollbar.error('Login error', error);
            };
            Alert.error(alertErr, {
              position: 'top-right',
              effect: 'stackslide',
              onShow: () => {},
              beep: false,
              timeout: 'none',
              offset: 100,
            });
          });
      } else if (!isEmail(values.email)) {
        setIsLoading(false);
        form.setFields([
          {
            name: 'email',
            errors: ['Please enter a valid email.'],
          },
        ]);
      } else setIsLoading(false);
    } catch {
      setIsLoading(false);
    }
  };
  // Might be need later
  // const onFocus = () => {
  //   if (browserCookies.get('token') && browserCookies.get('pytoken'))
  //     window.location.href = '/dashboard';
  // };
  // useEffect(() => {
  //   window.addEventListener('focus', onFocus);
  //   return () => {
  //     window.removeEventListener('focus', onFocus);
  //   };
  // }, []);

  const fieldErrors = getFieldsError()
  const fieldsHaveErrors = React.useMemo( () => fieldErrors.some( field => field.errors?.length ), [ fieldErrors ] )
  const fieldsAreEmpty = !getFieldValue('email') || !getFieldValue('password');

  return (
    <ButtonWrapper>
      <Button
        type="primary"
        htmlType="submit"
        disabled={fieldsHaveErrors || ( !shouldBeEnabled ? fieldsAreEmpty : false ) }
        loading={isLoading}
        onClick={handleSubmit}
      >
        Log in
      </Button>
      <TwoFACodeForm
        mfaModal={mfaModal}
        handleSubmit={handleSubmit}
        isLoading={isLoading}
        handleMfaModal={setMfaModal}
      />
    </ButtonWrapper>
  );
};
export default LoginSubmitButton;
