const LoginMainForm = (props) => {
  const { customer } = props;
  const [emailVal, setEmailVal] = React.useState(false);
  const [passwordVal, setPasswordVal] = React.useState(false);
  const [autoFilled, setAutoFilled] = React.useState(false);
  const emailInputRef = React.useRef();
  const passwordInputRef = React.useRef();
  const interval = React.useRef(null);
  const [form] = Form.useForm();

  const handleFormValuesChange = React.useCallback( ( _changedVals, vals ) => {
    setEmailVal( vals.email )
    setPasswordVal( vals.password )
  }, [] )

  React.useEffect(() => {
    form.resetFields();
    if (customer) {
      setEmailVal(customer.email)
      form.setFieldsValue({
        email: customer.email,
      });
    }
  }, [customer, form]);

  // Detect autofill in chrome
  React.useEffect(() => {
    interval.current = setInterval(() => {
      if (passwordInputRef?.current?.input && emailInputRef?.current?.input) {
        const emailStyles = window.getComputedStyle(
          emailInputRef.current.input
        );
        const passwordStyles = window.getComputedStyle(
          passwordInputRef.current.input
        );

        if (
          emailStyles.backgroundColor === 'rgb(232, 240, 254)' &&
          passwordStyles.backgroundColor === 'rgb(232, 240, 254)'
        ) {
          setAutoFilled(true);
          clearInterval(interval.current);
        }
      }
    }, 1000);

    return () => clearInterval(interval.current);
  }, []);

  const clearDetectInterval = React.useCallback(
    () => interval?.current && clearInterval(interval.current),
    []
  );

  return (
    <FormWrapper>
      <Form
        form={form}
        id="login-form"
        className="login-form"
        name="login-form"
        autoComplete="chrome-off"
        onFocus={clearDetectInterval}
        onValuesChange={ handleFormValuesChange }
        initialValues={{
          email: customer?.email || '',
        }}
      >
        <Alert />
        <FormItemStyled
          name="email"
          label="Email address*"
          data-has-value={ !!emailVal?.length || autoFilled }
          rules={[
            {
              required: true,
              whitespace: true,
              message: 'Please enter your work email.',
            },
            { validator: emailValidateRule },
          ]}
        >
          {/* <InputWrapper> */}
            <InputStyled
              name="UXCam-email"
              autoComplete="chrome-off"
              ref={emailInputRef}
            />
          {/* </InputWrapper> */}
        </FormItemStyled>
        <FormItemStyled
          name="password"
          label="Password*"
          data-has-value={ !!passwordVal?.length || autoFilled }
          rules={[{ required: true, message: 'Please enter your password.' }]}
        >
          <InputWrapper>
            <InputStyled
              ref={passwordInputRef}
              name="UXCam-password"
              autoComplete="chrome-off"
              className="password-input"
              type="password"
            />
          </InputWrapper>
        </FormItemStyled>
        <ForgotPassword />
        <FormItem shouldUpdate>
          {({ getFieldValue, getFieldsError }) => (
            <LoginSubmitButton
              getFieldValue={getFieldValue}
              getFieldsError={ getFieldsError }
              form={form}
              shouldBeEnabled={autoFilled}
              {...props}
            />
          )}
        </FormItem>
      </Form>
      <style>
        {`
            .ant-modal-confirm .ant-modal-body{
              padding-bottom: 20px !important;
            }
            .ant-modal-confirm .ant-modal-confirm-body-wrapper .ant-modal-confirm-btns .ant-btn{
              border-radius: 4px;
            }
            .ant-modal-confirm .ant-modal-confirm-body-wrapper .ant-btn-primary{
              background-color: #5D97FF;
              text-transform: uppercase;
              border:0;
            }
            .ant-modal-confirm-body .ant-modal-confirm-content {
              color: #161E35;
            }
            .s-alert-wrapper {
              position: relative!important;
              margin: 20px 0!important;
              color: #f04134;
            }
          `}
      </style>
    </FormWrapper>
  );
};
export default LoginMainForm;
