import React, { useState } from 'react';
import styled from 'styled-components';
import isEmail from 'validator/lib/isEmail';
import { Input, Button } from 'antd';
import axios from 'axios';

import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import { rollbar } from 'components/common/rollbar';

const FormWrapper = styled.div`
  width: 100%;

  input {
    font-size: 0.875rem;
    line-height: 1.375rem;
    padding: 13px 16px !important;
    border-radius: 4px;

    &:hover,
    &:active,
    &:focus {
      border-color: #5d97ff;
    }
  }

  button {
    margin-top: 36px;
    font-size: 1.125rem;
    line-height: 1.75rem;
    font-family: 'Poppins', Verdana, sans-serif;
    font-weight: 500;
    color: #ffffff;
    padding: 10px 24px;
    height: initial;
    border-radius: 4px;
    text-transform: initial;
    background-color: #5d97ff;
    transition: all 0.1s ease-in-out;

    &:hover {
      background-color: #151e35;
    }
  }
`;

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: center;
`;

const SSOSignIn = ({ redirectUrl }) => {
  const [ssoEmail, setSSOEmail] = useState('');
  const [error, setError] = useState({ isError: false, errorMsg: '' });
  const onSSOEmailChange = (event) => setSSOEmail(event?.target?.value?.trim());
  const processSSOLogin = async () => {
    await axios({
      method: 'post',
      url: `${process.env.API_URL}/sso/detail`,
      data: { email: ssoEmail },
      withCredentials: true,
    })
      .then((response) => {
        const responseUrl = response.data.data.redirectUrl;
        if (response.status === 200)
          redirectUrlHandler(`${responseUrl}?redirect=${btoa(redirectUrl)}`);
      })
      .catch((err) => {
        const message = err.response.data.error.error;
        setError({ isError: true, errorMsg: message });

        if (message === 'SSO not configured.') {
          return
        }
        rollbar.error('SSO signin error', err);
      });
  };
  const handleSSOLogin = () => processSSOLogin();
  return (
    <FormWrapper>
      <Input
        placeholder="Email Address"
        onChange={(e) => onSSOEmailChange(e)}
        onPressEnter={() => {
          ssoEmail && handleSSOLogin();
        }}
      />
      {error.isError && (
        <div className="ant-form-explain">{error.errorMsg}</div>
      )}
      <ButtonWrapper>
        <Button
          type="primary"
          htmlType="submit"
          disabled={ssoEmail.length < 1 || !isEmail(ssoEmail)}
          onClick={() => handleSSOLogin()}
        >
          Sign in
        </Button>
      </ButtonWrapper>
    </FormWrapper>
  );
};

export default SSOSignIn;
